+        allow: ["lossless-claw"],
+      }),
+      true,
+    );
+    expect(state).toEqual({ enabled: true });
+  });
 });
```

### ✨ 修复效果

修复后，`plugins.allow` 只会应用于：
- ❌ 非 bundled plugins（如 workspace plugins）
- ❌. 非 default-enabled 的 bundled plugins

而以下情况会豁免：
- ✅ 默认启用的 bundled plugins（如 BUNDLED_ENABLED_BY_DEFAULT 中的 providers）
- ✅ 通过 manifest metadata 设置默认启用的 bundled plugins
- ✅ 显式启用的 plugins（通过 `plugins.entries.<id>.enabled = true`）
- ✅ memory slot plugins

### 🎯 总结

修复成功解决了 issue #57219，bundled plugins 现在不会被 `plugins.allow` allowlist 错误阻塞。Telegram bot 及其他基于 bundled channels 的功能在设置了 `plugins.allow` 后仍然可以正常工作。
